\label{teorcondicion3caracterizacion}
Let $\M$ be a strongly regular sequence. Then
$d_{\M}(t)$ verifies condition~(\ref{OA3:1}) if, and only if,
\begin{equation}\label{limit.logmp.over.logp.omega}
    \lim_{p\ri \oo} \frac{\log (m_p)}{\log(p)}=\o(\M).
\end{equation}

\label{coroWatsonlemma}
Suppose $\M$ is strongly regular and such that $d_{\M}(t)$ is a proximate order, and let $\ga>0$ and a sectorial region $G_\ga$ be given. The following statements are equivalent:
\begin{itemize}
\item[(i)] $\tilde{\mathcal{A}}_{\M}(G_{\gamma})$ is quasianalytic.

\item[(ii)] $\gamma>\omega(\M)$.
\end{itemize}

For a strongly regular sequence $\M$, we define the \textit{order of quasianalyticity}
$$\omega(\M):=\inf \{\ga>0:\mathcal{\tilde{A}}_{\M}(G_{\gamma}) \textrm{ is quasianalytic}\}.
$$

For the sake of completeness, we will show more implications than strictly needed.\par
 (a) $\Rightarrow$ (b) According to \eqref{equaDefidM} and \eqref{equaRelationM_nu}

 we have that
$$d_{\M}'(t)=\frac{M'(t)}{\log(t)M(t)}-\frac{d_{\M}(t)}{t \log(t)}=
\frac{1}{t\log(t)}\left(\frac{\nu(t)}{M(t)}-d_{\M}(t)\right),$$
whenever it exists. Observe that (\ref{OA4:1}) in Definition~\ref{OAD:1} amounts then to
\begin{equation}\label{equaRephraseConditionDProxOrder}
\lim_{t\ri \oo} \Big(\frac{\nu(t)}{M(t)} - d_{\M}(t)\Big)=0. \end{equation}
By Theorem~\ref{theo.limsup.dM.omega} and condition (C) in Definition~\ref{OAD:1}, we know that $\lim_{t\ri\oo} d_{\M}(t) = 1/\o(\M)$, and so
\begin{equation*}
\lim_{t\ri \oo} \frac{\nu(t)}{M(t)}= \frac{1}{\o(\M)}. \end{equation*}
In particular,
$$
\lim_{p\ri \oo} \frac{\nu(m_p)}{M(m_p)}=\lim_{p\ri \oo} \frac{p+1}{M(m_p)}=\frac{1}{\o(\M)}. $$
Taking into account~(\ref{equation.M.in.mp}), the last limit may be written as
 \begin{equation*}
  \lim_{p\ri\oo} \log\left(\frac{m_p}{M_p^{1/p}}\right)=\o(\M),
 \end{equation*}
as desired. (b) $\Rightarrow$ (a) According to~\eqref{equaDefiAlfaBeta}, condition~(b) can be written as
\begin{equation}\label{equaLimitBetaOmega}
\lim_{p\ri\oo} \b_p=\o\in(0,\oo). \end{equation}
By using~(\ref{eqalfabeta}), we see that
\begin{equation*}
\lim_{p\ri\oo} \frac{(\a_{p+1}-\b_{p+1})-(\a_p-\b_p)}{\log(p+1)-\log(p)}=\lim_{p\ri\oo} \frac{\b_p/(p+1)}{1/p}=\o,
\end{equation*}
and then we deduce by Stolz's criterion that
\begin{equation*}
\lim_{p\ri\oo} \frac{\a_p-\b_p}{\log(p)}=\o. \end{equation*}
Since $\beta_p=O(1)$ (and $\a_p=\log(m_p)$), we get
\begin{equation}\label{equaAuxilLimit1}
\lim_{p \ri \oo} \frac{\log(m_p)}{\log(p)}=\o.

\label{mgomega6comparison}
Let $M,N\in\hyperlink{LCset}{\mathcal{LC}}$ be given with $M\le N$ and $\omega_{M}, \omega_{N}$ the corresponding associated weight functions. Then we get
$$\alpha(N,\Omega_M)=\frac{1}{\beta(\omega_{N},\omega_{M})}.$$

If we observe that the condition (snq) for $\M$ is precisely $(\gamma_1)$ for $\widehat{m}$, the sequence of quotients for $\hM$, and that $\ga(\hM)=\ga(\M)+1$ (this is clear from~\eqref{equa.indice.gammaM.casicrec}), we deduce from the second statement in~\eqref{equa.indice.gammaM.gamma_r} that
\begin{equation}\label{eq.snqiffgammaMpositive}
\textrm{$\M$ satisfies (snq) if, and only if, }\ga(\M)>0.
\end{equation}

Given a weight sequence $\M=(M_p)_{p\in\N_0}$, we write
$$\o_{\M}(t):=\sup_{p\in\N_0} \ln\left(\frac{t^{p}}{M_{p}}\right),\qquad t>0,$$
and $\o_{\M}(0)=0$. This is the classical
(continuous, nondecreasing)
function  associated with the sequence $\M$, see~\cite{komatsu}.

Another associated function will play a key-role, namely
\begin{equation*}
h_\M(t):=\inf_{p\in\N_0}M_p t^p, \quad t>0.
\end{equation*}
The functions $h_\M$ and $\omega_\M$ are related by
\begin{equation}\label{functionhequ2}
h_\M(t)=\exp(-\omega_\M(1/t)),\quad t>0.
\end{equation}

\label{propPropiedlcmg}
Let $\M=(M_p)_{p\in\N_0}$ be a sequence. Then, we have:
\begin{itemize}
\item[(i)] $\M$ is (lc) if, and only if, $\bm$ is nondecreasing. If, moreover, $\M$ satisfies (snq) then $\bm$ tends to infinity.
\item[(ii)] Suppose that $\M$ is (lc). Then,
\begin{itemize}
\item[(ii.1)]  $(M_p^{1/p})_{p\in\N}$ is nondecreasing, and $M_p^{1/p}\leq m_{p-1}$ for every $p\in\N$.\par
    Moreover, $\lim_{p\to\infty}m_p=\infty$ if, and only if, $\lim_{p\to\infty}M_p^{1/p}=\infty$.

\item[(ii.2)] The following statements are equivalent:
\begin{itemize}
  \item[(ii.2.a)]  $\M$ is (mg),
  \item[(ii.2.b)] $\sup_{p\in\N} m_p/M^{1/p}_p <\infty$,
  \item[(ii.2.c)]  $\sup_{p\in\N_0} m_{2p}/m_{p}<\infty$,
  \item[(ii.2.d)] $\sup_{p\in\N} \left(M_{2p}/M_p^2\right)^{1/p}<\infty$.
 \end{itemize}
\item[(ii.3)] If  $\M$ is (mg) and $A>0$ is the corresponding constant, then
\begin{equation*}
m_p^p\le A^{2p}M_p,\quad p\in\N_0.
\end{equation*}
\end{itemize}
\item[(iii)] If $(p!M_p)_{p\in\N_0}$ is (lc), then
 the following statements are equivalent:
 \begin{itemize}
 \item[(iii.1)] $\M$ verifies (snq).
 \item[(iii.2)] There exists $k\in\N$, $k\ge 2$, such that
 \begin{equation*}
  \liminf_{p\ri\oo} \frac{m_{kp}}{m_p}>1.
 \end{equation*}
 \end{itemize}
\end{itemize}

(i) $\Rightarrow$ (ii)  We call $\o$ the value of the limit in (i). If we consider the sequences
$(\a_p)_{p\in\N_0}$ and $(\b_p)_{p\in\N_0}$
defined in~\eqref{equaDefiAlfaBeta}, we will show that
$$\lim_{p\ri\oo}( \a_{\lfloor\lambda p\rfloor}-\a_p)=\o\log(\lambda),\qquad \lambda>0 ,$$
 which, by definition, implies condition (ii) and, moreover, by Theorem~\ref{theo.BojanicSeneta}, shows that the index of regular variation is equal to $\o$. For $\lambda=1$ the result is immediate. Assuming that $\lambda>1$, and using Lemma 3.8 in \cite{JimenezSanz} we know that
\begin{align}
  \a_p=&\sum^{p-1}_{k=0}\frac{\b_k}{k+1}+\b_p, \qquad p\in\N_0.\label{eqalfabeta}
 \end{align}
This leads to
\begin{equation}
 \a_{\lfloor\lambda p\rfloor}-\a_p=\sum^{\lfloor\lambda p\rfloor-1}_{k=p}\frac{\b_k}{k+1}+\b_{\lfloor\lambda p\rfloor}-\b_p.\no
\end{equation}
Condition~(i) can be written as
$\lim_{p\ri\oo}\b_p=\o$,
so it is sufficient to prove that
$$\lim_{p\ri\oo} \sum^{\lfloor\lambda p\rfloor-1}_{k=p}\frac{\b_k}{k+1} =\o\log(\lambda).$$
If we take $\ep>0$, we fix $\delta>0$ such that $\delta\log(\lambda)<\ep/6$. There exists $p_\delta\in\N$ such that
$|\b_p-\o|<\delta$ for $p\geq p_\delta$. We remember that the $p-$th partial sum $H_p=\sum_{k=1}^p 1/k$ of the harmonic series may be given as
\begin{equation}\label{equaPartialSumsHarmonic}
H_p=\log(p)+\ga+\ep_p,\qquad \ga=\textrm{Euler's constant},\ \lim_{p\ri\oo} \ep_p=0.

\label{remaRieszMethod}
By using~(\ref{eqalfabeta}) and Stolz's criterion we easily deduce that~\eqref{equaCondEquivBetaOmega} implies \eqref{equaCondEquivLogmpOverLogpOmega}.

To prove the converse, we need to recall the Riesz weighted average summability method for sequences, also called sequence summation by logarithmic means.
